function inspect(){
  const report=[];
  // gather component/symbol info across file
  const compNodes=[];
  function walk(n){
    if(n.type==='COMPONENT') compNodes.push({id:n.id,name:n.name,key:n.key});
    if(n.children) n.children.forEach(walk);
  }
  figma.root.children.forEach(walk);
  const wanted=['Status Bar','Home Indicator','Button','Logo_Meet','Icon_Heart','Icon_Home','Icon_Close','Portrait_Sarah_Payne','Portrait_Claire_Smith','Portrait_John','Portrait_Yu_Jian','Post_Yu_Jian','Short_Yu_Jian_Shore','Claire_01_Video_Ocean','Sarah_01_Video_Wave','Icon_Google','Icon_Facebook','Icon_Plus','Icon_Bell','Icon_Chat','Icon_More','Icon_Location','Icon_Dating'];
  compNodes.filter(c=>wanted.some(w=>c.name.includes(w))).forEach(c=>{
    report.push(c.id+' :: '+c.name);
  });
  return report.join('\n');
}
