async function run(){
  const page = figma.currentPage;
  // create 8 frames
  const frames = {};
  const specs = [
    ['01_Welcome',0],
    ['02_Apple_ID_Sheet',500],
    ['03_Explore',1000],
    ['04_Find_Partner',1500],
    ['05_Friend_Profile',2000],
    ['06_Short_Video',2500],
    ['07_Profile',3000],
    ['08_Menu',3500],
  ];
  for(const [name,x] of specs){
    const f = figma.createFrame();
    f.name=name; f.resize(393,852); f.x=x; f.y=0;
    f.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}];
    f.clipsContent=true;
    page.appendChild(f);
    frames[name]=f;
  }
  // helper to instantiate component
  function inst(id,p){
    const comp = figma.getNodeById(id);
    const it = comp.createInstance();
    p.appendChild(it);
    return it;
  }
  // add status bar + home indicator to each
  for(const name of Object.keys(frames)){
    const f=frames[name];
    const sb=inst('1:33',f); sb.x=0; sb.y=0;
    const hi=inst('1:44',f); hi.x=0; hi.y=818;
  }
  // return created frame ids
  let out={};
  for(const name of Object.keys(frames)){ out[name]=frames[name].id; }
  return JSON.stringify(out);
}
