function findComponent(nameMatch){
  let hit=null;
  function walk(n){
    if(n.type==='COMPONENT' && n.name.includes(nameMatch)){hit=n;}
    if(n.children && !hit){n.children.forEach(walk);}
  }
  figma.root.children.forEach(walk);
  return hit;
}
