async function addTab(frameId,currentLabel){
const page=figma.root.children.find(p=>p.name==='03 · Workspace');
await figma.setCurrentPageAsync(page);
const fr=figma.getNodeById(frameId);
const tbcomp=figma.getNodeById('19:99');
const inst=tbcomp.createInstance();
inst.x=0;inst.y=769;inst.name='TabBar';
fr.appendChild(inst);
// Identify current tab by label x position within component
// label centers stored as keys labelHome etc. Instead find label text
const plum={r:0.29,g:0.09,b:0.30};const act={r:0.45,g:0.44,b:0.46};
function recolor(textStr,color,labelColor){
  const children=inst.children;
  for(const ch of children){
    if(ch.type==='TEXT' && ch.characters===textStr){ ch.fills=[{type:'SOLID',color:labelColor}]; }
    if(ch.type==='INSTANCE' && ch.children&&ch.children[0]&&ch.children[0].type==='VECTOR'&&ch.children[0].name.toLowerCase().includes(textStr.toLowerCase())){}
  }
}
// find icon instance at same x as the label
const lbl=inst.children.find(c=>c.type==='TEXT'&&c.characters===currentLabel);
if(lbl){
  lbl.fills=[{type:'SOLID',color:plum}];
  const lx=lbl.x;
  const icon=inst.children.find(c=>c.type==='INSTANCE'&&Math.abs(c.x-lx)<12);
  if(icon){ const v=findVec(icon); if(v)v.fills=[{type:'SOLID',color:plum}]; }
}
}
function findVec(n){
  if(!n||!n.children)return null;
  for(const c of n.children){ if(c.type==='VECTOR')return c; }
  for(const c of n.children){ const r=findVec(c); if(r)return r; }
  return null;
}
