async function main() {
  const page = figma.root.children.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(page);
  const comp = new Map();
  function walk(n) { if (n.type === 'COMPONENT') comp.set(n.name, n); if (n.children) n.children.forEach(walk); }
  figma.root.children.forEach(walk);
  function inst(name) { const c = comp.get(name); if (!c) throw new Error('no comp ' + name); return c.createInstance(); }
  const FR = { family: 'Inter', style: 'Regular' };
  const FM = { family: 'Inter', style: 'Medium' };
  const FB = { family: 'Inter', style: 'Bold' };
  await figma.loadFontAsync(FR); await figma.loadFontAsync(FM); await figma.loadFontAsync(FB);
  const fr = figma.getNodeById('9:4');
  function txt(str, x, y, size, w, style) { const t = figma.createText(); t.characters = str; t.fontName = style || FR; t.fontSize = size; t.x = x; t.y = y; if (w) t.resize(w, size + 8); t.fills = [{ type: 'SOLID', color: { r: 0.29, g: 0.09, b: 0.3 } }]; fr.appendChild(t); return t; }
  // 1. Stories row header
  txt('Stories', 16, 92, 13, 100, FM);
  // 2. Segmented control (Make Friends / Search Partners) below stories
  return 'ok';
}
main().catch(e => console.log('E ' + e.message));
